1	package org.springframework.samples.petclinic.model;
2	
3	import java.util.Map;
4	
5	/**
6	 * Pinned city-to-region reference data. Maps a known city to its canonical region string;
7	 * any city not in the table resolves to {@link #UNKNOWN}.
8	 */
9	public final class Locality {
10	
11	    /** The locality returned for a city that is not in the table. */
12	    public static final String UNKNOWN = "UNKNOWN";
13	
14	    /** City -> canonical region. */
15	    private static final Map<String, String> CITY_REGION = Map.of(
16	            "Sydney", "NSW",
17	            "Melbourne", "VIC",
18	            "Brisbane", "QLD");
19	
20	    /** Region -> inclusive 4-digit postcode range {low, high}. */
21	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
22	            "NSW", new int[] {2000, 2099},
23	            "VIC", new int[] {3000, 3099},
24	            "QLD", new int[] {4000, 4099});
25	
26	    private Locality() {
27	    }
28	
29	    /**
30	     * Derive the canonical region for the given city.
31	     *
32	     * @param city the owner's city (may be {@code null})
33	     * @return the canonical region string, or {@link #UNKNOWN} when the city is not in the table
34	     */
35	    public static String regionFor(String city) {
36	        return CITY_REGION.getOrDefault(city, UNKNOWN);
37	    }
38	
39	    /**
40	     * Whether the given 4-digit postcode is permitted for the given city. A city whose
41	     * region has a pinned postcode range accepts only postcodes within that (inclusive)
42	     * range; a city with no known region accepts any postcode.
43	     *
44	     * @param city     the owner's city (may be {@code null})
45	     * @param postcode the numeric value of a 4-digit postcode
46	     * @return {@code true} when the postcode is allowed for the city's region
47	     */
48	    public static boolean postcodeAllowedForCity(String city, int postcode) {
49	        int[] range = REGION_POSTCODES.get(regionFor(city));
50	        return range == null || (postcode >= range[0] && postcode <= range[1]);
51	    }
52	}
