2	
3	import java.util.Locale;
4	
5	import org.springframework.samples.petclinic.model.Owner;
6	
7	/**
8	 * The single definition of how owners are grouped by city: compared case-insensitively.
9	 * Shared by {@link AssignOwnerCustomerCode} (which derives the per-city sequence) and
10	 * {@link RejectFullOwnerCity} (which caps a city's population), so both count a city's
11	 * members identically.
12	 */
13	final class OwnerCities {
14	
15	    private OwnerCities() {
16	    }
17	
18	    /** The number of existing owners in {@code city}. */
19	    static int size(Iterable<Owner> owners, String city) {
20	        int count = 0;
21	        for (Owner existing : owners) {
22	            if (city != null && city.equalsIgnoreCase(existing.getCity())) {
23	                count++;
24	            }
25	        }
26	        return count;
27	    }
28	}
