8	import org.springframework.samples.petclinic.rest.escalation.InvalidPostcodeException;
9	
10	/**
11	 * Validates an owner request's optional postcode. When absent the request is accepted
12	 * unchanged; when present it must be four digits and, for a city whose region has a pinned
13	 * postcode range, fall within that range (see {@link Locality#postcodeAllowedForCity}).
14	 * Otherwise a {@link InvalidPostcodeException} is thrown (400). Reads the request already
15	 * published by an earlier step, so it sees the same normalized city later steps persist.
16	 */
17	public class ValidateOwnerPostcode {
18	
19	    private static final Pattern FOUR_DIGITS = Pattern.compile("[0-9]{4}");
20	
21	    public void service(@Val OwnerFieldsDto request) throws InvalidPostcodeException {
22	        String postcode = request.getPostcode();
23	        if (postcode == null) {
24	            return;
25	        }
26	        if (!FOUR_DIGITS.matcher(postcode).matches()) {
27	            throw new InvalidPostcodeException("Postcode must be 4 digits, but was '" + postcode + "'");
28	        }
29	        if (!Locality.postcodeAllowedForCity(request.getCity(), Integer.parseInt(postcode))) {
30	            throw new InvalidPostcodeException(
31	                    "Postcode " + postcode + " is not valid for city '" + request.getCity() + "'");
32	        }
33	    }
34	}
