1	package org.springframework.samples.petclinic.mapper;
2	
3	import org.jspecify.annotations.NonNull;
4	import org.mapstruct.Mapper;
5	import org.mapstruct.Mapping;
6	import org.springframework.data.domain.Page;
7	import org.springframework.samples.petclinic.model.Locality;
8	import org.springframework.samples.petclinic.model.Owner;
9	import org.springframework.samples.petclinic.model.OwnerIdentity;
10	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
11	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
12	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
13	
14	import java.util.Collection;
15	import java.util.List;
16	
17	/**
18	 * Maps Owner & OwnerDto using Mapstruct
19	 */
20	@Mapper(uses = PetMapper.class)
21	public interface OwnerMapper {
22	
23	    @Mapping(target = "displayName", expression = "java(displayName(owner))")
24	    @Mapping(target = "initials", expression = "java(initials(owner))")
25	    @Mapping(target = "membershipNumber", expression = "java(membershipNumber(owner))")
26	    @Mapping(target = "membershipLevel", expression = "java(membershipLevel(owner))")
27	    @Mapping(target = "locality", expression = "java(locality(owner))")
28	    @Mapping(target = "contactPreference", expression = "java(contactPreference(owner))")
29	    @Mapping(target = "identityKey", expression = "java(identityKey(owner))")
30	    OwnerDto toOwnerDto(Owner owner);
31	
32	    Owner toOwner(OwnerDto ownerDto);
33	
34	    /** Format an owner's name as 'LastName, FirstName' for display. */
35	    default String displayName(Owner owner) {
36	        return owner.getLastName() + ", " + owner.getFirstName();
37	    }
38	
39	    /** The upper-cased first letters of firstName and lastName, dot-separated with a trailing dot. */
40	    default String initials(Owner owner) {
41	        return initial(owner.getFirstName()) + initial(owner.getLastName());
42	    }
43	
44	    private static String initial(String name) {
45	        return Character.toUpperCase(name.charAt(0)) + ".";
46	    }
47	
48	    /** The owner's membership number, formatted '&lt;customerCode&gt;-M&lt;YY&gt;' where YY is the
49	     * last two digits of the registrationDate year. */
50	    default String membershipNumber(Owner owner) {
51	        if (owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
52	            return null;
53	        }
54	        return String.format("%s-M%02d", owner.getCustomerCode(), owner.getRegistrationDate().getYear() % 100);
55	    }
56	
57	    /** The owner's membership level from 1 to 3: starts at 1, plus 1 when an email is present,
58	     * plus 1 when namesakeCount is 0, capped at 3 (level 4 is reserved for tenure). */
59	    default int membershipLevel(Owner owner) {
60	        int level = 1;
61	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
62	        if (hasEmail) {
63	            level++;
64	        }
65	        if (owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0) {
66	            level++;
67	        }
68	        return Math.min(level, 3);
69	    }
70	
71	    /** The owner's canonical region, derived from the city via the pinned city-to-region table,
72	     * or 'UNKNOWN' when the city is not in the table. */
73	    default String locality(Owner owner) {
74	        return Locality.regionFor(owner.getCity());
75	    }
76	
77	    /** The owner's preferred contact channel: 'EMAIL' when an email is present, otherwise 'PHONE'. */
78	    default String contactPreference(Owner owner) {
79	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
80	        return hasEmail ? "EMAIL" : "PHONE";
81	    }
82	
83	    /** The owner's derived identity key (see {@link OwnerIdentity}). */
84	    default String identityKey(Owner owner) {
85	        return OwnerIdentity.of(owner);
86	    }
87	
88	    @Mapping(target = "id", ignore = true)
89	    @Mapping(target = "pets", ignore = true)
90	    @Mapping(target = "customerCode", ignore = true)
91	    @Mapping(target = "householdId", ignore = true)
92	    @Mapping(target = "namesakeCount", ignore = true)
93	    @Mapping(target = "householdSize", ignore = true)
94	    @Mapping(target = "bulkSignupWarning", ignore = true)
95	    Owner toOwner(OwnerFieldsDto ownerDto);
96	
97	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
98	
99	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
100	
101	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
102	        OwnerPageDto ownerPageDto = new OwnerPageDto();
103	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
104	        ownerPageDto.setPage(ownerPage.getNumber());
105	        ownerPageDto.setSize(ownerPage.getSize());
106	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
107	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
108	        return ownerPageDto;
109	    }
110	}
