1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.repository.OwnerRepository;
5	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
6	import org.springframework.samples.petclinic.rest.escalation.CityAtCapacityException;
7	
8	/**
9	 * Rejects a create-owner request whose city already holds {@link #CITY_CAPACITY} or more
10	 * owners, responding 409. City membership is counted case-insensitively via
11	 * {@link OwnerCities}, the same definition {@link AssignOwnerCustomerCode} uses.
12	 */
13	public class RejectFullOwnerCity {
14	
15	    /** Maximum number of owners a single city may hold. */
16	    static final int CITY_CAPACITY = 50;
17	
18	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
19	            throws CityAtCapacityException {
20	        if (OwnerCities.size(ownerRepository.findAll(), request.getCity()) >= CITY_CAPACITY) {
21	            throw new CityAtCapacityException(request.getCity(), CITY_CAPACITY);
22	        }
23	    }
24	}
